[CmdletBinding()]
param([switch]$Generate)
$ErrorActionPreference='Stop';$repo=Split-Path $PSScriptRoot -Parent;$e=Join-Path $repo 'evidence/phase-0b-u006-primary-profile';$report='docs/reports/2026-09-19T0715Z-phase-0b-u006-primary-profile.md'
$relative=@('scripts/phase0b-extension-recorder-primary.cjs','scripts/phase0b-u006-primary-watchdog.ps1','scripts/phase0b-u006-primary-restore.ps1','scripts/phase0b-verify-primary-profile.ps1',$report)+@(Get-ChildItem $e -Filter '*.json'|Where-Object{$_.Name -notin @('security-gate.json','evidence-manifest.json')}|ForEach-Object{$_.FullName.Substring($repo.Length+1).Replace('\','/')})
$absolute=@($relative|ForEach-Object{Join-Path $repo $_});$violations=@();$pathPattern='(?i)\b[A-Z]:\\';$secretPatterns=@('(?i)Bearer\s+[A-Za-z0-9._~-]{12,}','(?i)-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----','(?i)(?:access|refresh)[_-]?token\s*[:=]','(?i)\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b')
foreach($file in $absolute){if(-not(Test-Path $file)){throw "MISSING_ARTIFACT:$file"};$text=Get-Content -Raw $file;if($text-match$pathPattern){$violations+='ABSOLUTE_LOCAL_PATH'};foreach($p in $secretPatterns){if($text-match$p){$violations+='SECRET_OR_IDENTITY_PATTERN'}};if($file.EndsWith('.json')){$text|ConvertFrom-Json|Out-Null}}
