if($Generate){$enc=New-Object Text.UTF8Encoding($false);[IO.File]::WriteAllText((Join-Path $e 'security-gate.json'),($gate|ConvertTo-Json -Depth 20)+"`n",$enc);$files=@($absolute+(Join-Path $e 'security-gate.json'));$manifest=@{schema_version='1';status='PASS';artifacts=@($files|ForEach-Object{$h=Get-FileHash $_ -Algorithm SHA256;[ordered]@{path=$_.Substring($repo.Length+1).Replace('\','/');sha256=$h.Hash;size=(Get-Item $_).Length}})};[IO.File]::WriteAllText((Join-Path $e 'evidence-manifest.json'),($manifest|ConvertTo-Json -Depth 20)+"`n",$enc);$check=Get-Content -Raw (Join-Path $e 'evidence-manifest.json')|ConvertFrom-Json;foreach($item in $check.artifacts){if((Get-FileHash (Join-Path $repo $item.path) -Algorithm SHA256).Hash-ne$item.sha256){throw 'MANIFEST_HASH_VERIFY_FAILED'}}}
$gate|ConvertTo-Json -Depth 20
